def calcular_perfil():
    p=(st.session_state.reputacion+st.session_state.etica+st.session_state.calidad)/3
    if p>=82: return "Editor/a Experto/a"
    if p>=68: return "Investigador/a Estratégico/a"
    if p>=52: return "Explorador/a Editorial"
    return "Investigador/a en alerta"

def resultado_formulario():
    header()
    st.title("🏆 Resultado final")
    mostrar_metricas()
    perfil=calcular_perfil(); st.session_state.perfil=perfil
    st.success(f"Tu perfil obtenido es: **{perfil}**")
    textos = {
        "Editor/a Experto/a":"Tomaste decisiones sólidas, éticas y orientadas a la calidad editorial.",
        "Investigador/a Estratégico/a":"Elegiste con criterio y mostraste buen manejo del circuito editorial.",
        "Explorador/a Editorial":"Vas por buen camino, aunque todavía conviene fortalecer algunos criterios de evaluación editorial.",
        "Investigador/a en alerta":"Algunas decisiones podrían llevarte a riesgos editoriales. Revisá las señales de alerta antes de publicar."
    }
    st.write(textos[perfil])
    if st.session_state.logros:
        st.markdown("### Tus insignias")
        st.markdown(" ".join([f'<span class="logro">🏅 {l}</span>' for l in st.session_state.logros]), unsafe_allow_html=True)

    st.markdown('<div class="caja"><b>Lo que trabajaste en esta aventura:</b><br>✓ Revistas depredadoras y señales de alerta.<br>✓ Acceso Abierto, Ruta Oro y Ruta Diamante.<br>✓ Instrucciones para autores.<br>✓ Uso responsable de Inteligencia Artificial.<br>✓ Selección de revistas pertinentes para tu vector de investigación.</div>', unsafe_allow_html=True)

    st.divider()
    st.subheader("🤝 Aportá una revista a la Biblioteca Colaborativa")
    st.write("Para finalizar la actividad, registrá una revista científica de Acceso Abierto Diamante vinculada con tu vector de investigación.")

    with st.form("form_revista"):
        nombre=st.text_input("Nombre y apellido")
        vector=st.selectbox("Vector estratégico", VECTORES, index=VECTORES.index(st.session_state.vector) if st.session_state.vector in VECTORES else 0)
        linea=st.text_input("Línea de investigación o tema del proyecto")
        revista=st.text_input("Nombre de la revista")
        disciplina=st.text_input("Disciplina")
        portal=st.selectbox("Portal donde la encontraste", ["SciELO","Redalyc","Latindex Catálogo 2.0","DOAJ","Google Scholar","Otro"])
        apc=st.selectbox("¿Cobra APC?", ["No","Sí","No encontré información"])
        norma=st.text_input("Norma de citación que utiliza")
        link=st.text_input("Link de la revista")
        justificacion=st.text_area("¿Por qué la elegiste?")

        st.markdown("### Sobre tu búsqueda")
        formas = st.multiselect(
            "¿Cómo encontraste o seleccionaste esta revista?",
            ["Busqué en SciELO", "Busqué en Redalyc", "Busqué en Latindex Catálogo 2.0", "Busqué en DOAJ", "Busqué en Google Scholar", "Consulté con mi director/a o equipo", "Consulté a una herramienta de IA", "Otra fuente"]
        )
        uso_ia = st.radio("¿Usaste IA para buscar o comparar revistas?", ["No", "Sí"], horizontal=True)
        verificacion_ia = "No corresponde"
        if uso_ia == "Sí":
            verificacion_ia = st.selectbox(
                "Si usaste IA, ¿cómo verificaste la información?",
                [
                    "Verifiqué en el sitio oficial de la revista",
                    "Verifiqué en SciELO, Redalyc, Latindex o DOAJ",
                    "Comparé con varias fuentes confiables",
                    "Consulté con mi director/a o equipo",
                    "No verifiqué la información"
                ]
            )
        enviar=st.form_submit_button("Guardar aporte en la Biblioteca")

    if enviar:
        campos=[nombre,vector,linea,revista,disciplina,portal,apc,norma,link,justificacion]
        if any(not str(c).strip() for c in campos):
            st.warning("Completá todos los campos principales antes de enviar.")
        else:
            if not formas:
                formas = ["No especificado"]
            nuevo={
                "Fecha":datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "Vector estratégico":vector,
                "Línea de investigación":linea,
                "Nombre y apellido":nombre,
                "Nombre de la revista":revista,
                "Disciplina":disciplina,
                "Portal":portal,
                "Cobra APC":apc,
                "Norma de citación":norma,
                "Link de la revista":link,
                "Justificación":justificacion,
                "Cómo encontró la revista":"; ".join(formas),
                "Usó IA para buscar":uso_ia,
                "Verificación de IA":verificacion_ia,
                "Perfil obtenido":perfil,
                "Reputación científica":st.session_state.reputacion,
                "Ética":st.session_state.etica,
                "Calidad editorial":st.session_state.calidad
            }
            guardar_aporte(nuevo)
            st.success("Tu aporte fue guardado correctamente. Ya forma parte de la Biblioteca Colaborativa.")
            st.balloons()
            st.markdown('<div class="caja"><b>Registro completo.</b><br>Además de cargar la revista, dejaste registrada la forma en que la encontraste y cómo verificaste la información. Esto ayuda a construir una biblioteca más confiable para todos los becarios.</div>', unsafe_allow_html=True)
            st.button("Ver Biblioteca", on_click=go_biblioteca)
    st.divider(); st.button("Reiniciar aventura", on_click=reset_aventura)

def biblioteca():
    header(); st.title("📚 Biblioteca Colaborativa de Revistas Científicas")
    st.write("Este espacio reúne revistas científicas recomendadas por los becarios del Programa Becas Chaco+i.")
    df=cargar_datos()
    if df.empty:
        st.info("Todavía no hay revistas cargadas. Las primeras aparecerán cuando los becarios completen la aventura."); return
    c1,c2,c3=st.columns(3); c1.metric("Revistas registradas", len(df)); c2.metric("Becarios participantes", df["Nombre y apellido"].nunique()); c3.metric("Vectores", df["Vector estratégico"].nunique())
    busq=st.text_input("Buscar por revista, línea, disciplina o portal")
    vector=st.selectbox("Filtrar por vector estratégico", ["Todos"]+VECTORES)
    filt=df.copy()
    if vector != "Todos": filt=filt[filt["Vector estratégico"]==vector]
    if busq:
        txt=busq.lower(); filt=filt[filt.astype(str).apply(lambda fila: fila.str.lower().str.contains(txt).any(), axis=1)]
    st.write(f"Resultados encontrados: **{len(filt)}**")
    for _,r in filt.iterrows():
        st.markdown('<div class="tarjeta">', unsafe_allow_html=True)
        st.markdown(f"### {r['Nombre de la revista']}")
        st.write(f"**Vector:** {r['Vector estratégico']}")
        st.write(f"**Línea:** {r['Línea de investigación']}")
        st.write(f"**Disciplina:** {r['Disciplina']} · **Portal:** {r['Portal']} · **APC:** {r['Cobra APC']}")
        st.write(f"**Norma de citación:** {r['Norma de citación']}")
        st.write(f"**Aporte de:** {r['Nombre y apellido']}")
        st.write(f"**Justificación:** {r['Justificación']}")
        if 'Cómo encontró la revista' in r.index and str(r.get('Cómo encontró la revista','')).strip():
            st.write(f"**Cómo la encontró:** {r.get('Cómo encontró la revista','')}")
        if 'Usó IA para buscar' in r.index and str(r.get('Usó IA para buscar','')).strip():
            st.write(f"**Uso de IA:** {r.get('Usó IA para buscar','')} · **Verificación:** {r.get('Verificación de IA','')}")
        if str(r['Link de la revista']).startswith('http'): st.link_button("Abrir revista", r['Link de la revista'])
        st.markdown('</div>', unsafe_allow_html=True)

def conceptos():
    header(); st.title("📖 Conceptos clave")
    st.write("Esta sección reúne conceptos breves que aparecen durante la aventura y ayudan a tomar mejores decisiones.")

    with st.expander("¿Qué es el circuito de publicación científica?", expanded=True):
        st.write("Es el proceso mediante el cual un manuscrito se envía a una revista, es revisado por editores y pares evaluadores, recibe observaciones y puede ser aceptado, rechazado o enviado a corrección. A diferencia de una publicación informal, busca validar el rigor, la originalidad y la pertinencia del trabajo.")

    with st.expander("Acceso Abierto: Ruta Diamante y Ruta Oro"):
        st.markdown("""
        - **Ruta Diamante:** la revista no cobra al autor por publicar ni al lector por acceder. Es muy frecuente en revistas sostenidas por universidades, sociedades científicas e instituciones públicas.
        - **Ruta Oro:** el artículo queda disponible para lectores, pero la revista puede cobrar una APC al autor o a su institución.
        """)

    with st.expander("¿Qué son las APC?"):
        st.write("APC significa Article Processing Charge. Es un cargo que algunas revistas cobran para procesar o publicar un artículo. Que una revista cobre APC no la vuelve automáticamente depredadora, pero el costo debe ser claro, transparente y justificado.")

    with st.expander("Revistas depredadoras"):
        st.write("Son publicaciones que aparentan ser científicas, pero priorizan el cobro por encima de la evaluación académica. Suelen prometer publicación muy rápida, enviar invitaciones genéricas y no transparentar adecuadamente su revisión por pares, comité editorial o indexación.")


    with st.expander("Portales y catálogos para buscar revistas"):
        st.markdown("""
        - **Latindex Catálogo 2.0:** permite identificar revistas académicas que cumplen criterios de calidad editorial.
        - **SciELO:** biblioteca científica de acceso abierto con revistas evaluadas y reconocidas en la región.
        - **Redalyc:** red de revistas científicas de acceso abierto, especialmente fuerte en América Latina.
        - **DOAJ:** directorio internacional de revistas de acceso abierto.
        """)

    with st.expander("Instrucciones para autores"):
        st.write("Son las normas de la revista para preparar y enviar un manuscrito. Allí se revisa el alcance de la revista, estructura del artículo, extensión, formato, normas de citación, documentos requeridos, tablas, figuras, ética y posibles declaraciones obligatorias.")

    with st.expander("Uso responsable de IA"):
        st.write("La IA puede ayudar a mejorar claridad, estilo, traducción o búsqueda inicial de información, pero el investigador debe verificar las respuestas en fuentes confiables. La IA no debe inventar datos, resultados, referencias ni figurar como autora del artículo.")
    st.markdown('<div class="caja"><b>Idea clave:</b> una buena decisión editorial combina pertinencia temática, transparencia, revisión por pares, costos claros e información verificada.</div>', unsafe_allow_html=True)


def recursos():
    header(); st.title("🧰 Caja de herramientas")
    st.write("Recursos útiles para buscar revistas, organizar bibliografía y preparar manuscritos.")
    c1,c2=st.columns(2)
    with c1:
        st.subheader("Portales para buscar revistas")
        st.markdown("- **Latindex Catálogo 2.0**\n- **SciELO**\n- **Redalyc**")
    with c2:
        st.subheader("Herramientas de apoyo")
        st.markdown("- **Zotero / Mendeley:** gestores bibliográficos.\n- **DeepL:** traducción asistida.\n- **LanguageTool / Grammarly:** revisión de estilo y escritura.")
    st.markdown('<div class="caja"><b>Recordatorio:</b> las herramientas de IA pueden apoyar la redacción, traducción o revisión de estilo, pero no reemplazan la responsabilidad del investigador sobre datos, resultados e interpretaciones.</div>', unsafe_allow_html=True)

